// This file is generated by AI.

// 场景配音编辑器: Monaco 编辑器 (上) + 语句配音操作台 (下)。
//
// 与普通场景编辑卡共享同一份文档与 Monaco model (因此不存在"冻结快照"):
// 解析结果随文档内容变化重新解析并重新匹配历史。
// 操作台高度固定, 光标移出对话时只清空内容而不改变布局。

import { Button } from '@fluentui/react-components';
import { ArrowSyncRegular } from '@fluentui/react-icons';
import { useEffect, useRef, useState } from 'react';

import type { SayLine } from '../commands/voice';
import { CodeEditor } from '../components/CodeEditor';
import { absToRel } from '../git/util';
import { useAppStore } from '../state/store';
import { makeDiffTab, sceneTabId } from '../tabs/model';
import { voiceController, DISK_CHECK_MS } from './controller';
import { dialogueAtLine } from './types';
import { SceneConflictDialog } from './SceneConflictDialog';
import { SentenceVoicePanel } from './SentenceVoicePanel';
import { VoiceTakeList } from './VoiceTakeList';

export function SceneVoiceEditor({ docPath }: { docPath: string }) {
  const doc = useAppStore((state) => state.documents.find((item) => item.path === docPath));
  // 订阅队列变化
  useAppStore((state) => state.voiceTick);
  const card = voiceController.getCard(docPath);
  const isActiveTab = useAppStore((state) => state.activeTabId) === sceneTabId(docPath);
  const characters = useAppStore((state) => state.voiceCharacters);
  const projectPath = useAppStore((state) => state.projectPath);
  const gitStatus = useAppStore((state) => state.gitStatus);
  const [refreshToken, setRefreshToken] = useState(0);
  const [conflictOpen, setConflictOpen] = useState(false);

  const previousContent = useRef<string | null>(null);

  // 首次挂载: 建卡 (解析对话 + 匹配角色)
  useEffect(() => {
    if (!doc) return;
    let disposed = false;
    void (async () => {
      const existing = voiceController.getCard(docPath);
      if (!existing) {
        await voiceController.openCard(docPath, docPath, doc.content, hash(doc.content));
      }
      if (!disposed) setRefreshToken((token) => token + 1);
    })();
    return () => {
      disposed = true;
    };
  }, [docPath]);

  // 文档内容变化 -> 重新解析
  useEffect(() => {
    if (!doc) return;
    if (previousContent.current === doc.content) return;
    const isFirstObservation = previousContent.current === null;
    previousContent.current = doc.content;
    if (isFirstObservation) return;
    void voiceController.refreshCard(docPath, doc.content).then(() => setRefreshToken((token) => token + 1));
  }, [doc?.content, docPath]);

  // 本地文件变更检测: 该卡为活动选项卡时 + 定时轮询。
  // 检测到变更后**先请用户裁决**, 裁决完成才重新对齐历史 (顺序不可颠倒)。
  useEffect(() => {
    if (!isActiveTab) return;
    let disposed = false;

    const check = async () => {
      if (disposed) return;
      const changed = await voiceController.checkDiskChange(docPath);
      if (!disposed && changed) setConflictOpen(true);
    };

    void check();
    const timer = setInterval(() => void check(), DISK_CHECK_MS);
    const onFocus = () => void check();
    window.addEventListener('focus', onFocus);
    return () => {
      disposed = true;
      clearInterval(timer);
      window.removeEventListener('focus', onFocus);
    };
  }, [isActiveTab, docPath]);

  /*
   * 光标位置变化 -> 定位当前对话。
   *
   * 判定必须按语句的 `[首行, 首行 + 行数)` 区间, 而不是"行号相等":
   * WebGAL 语句可以跨行, 只比首行会出现"光标在对话上一行/下一行才识别"的错乱。
   */
  const cursorLine = useAppStore((state) => state.cursor?.line ?? null);
  useEffect(() => {
    if (!isActiveTab || cursorLine === null) return;
    const current = voiceController.getCard(docPath);
    if (!current) return;
    const hit = dialogueAtLine(current.dialogues, cursorLine - 1);
    voiceController.setCursorLine(docPath, hit ? hit.line : null);
  }, [cursorLine, isActiveTab, docPath]);

  if (!doc) return null;
  if (!card) {
    return <div className="scene-voice-loading">正在解析场景…</div>;
  }

  const dialogue: SayLine | null = dialogueAtLine(card.dialogues, card.cursorLine ?? -1);

  return (
    <div className="scene-voice">
      <div className="scene-voice-editor">
        {/*
          只读编辑器: 配音卡只负责"读场景 + 选中语句", 编辑一律回到普通场景卡完成。
          当前语句整行高亮, 让"正在为哪一句配音"一目了然。
        */}
        <CodeEditor
          doc={doc}
          readOnly
          highlightLine={dialogue ? { line: dialogue.line, count: dialogue.lineCount } : null}
        />
      </div>

      <div className="scene-voice-panel">
        {dialogue ? (
          <div className="scene-voice-split">
            <SentenceVoicePanel
              cardId={docPath}
              dialogue={dialogue}
              characters={characters}
              refreshToken={refreshToken}
              onChanged={() => setRefreshToken((token) => token + 1)}
            />
            <VoiceTakeList
              cardId={docPath}
              onChanged={() => setRefreshToken((token) => token + 1)}
              onApplied={() => setRefreshToken((token) => token + 1)}
            />
          </div>
        ) : (
          <div className="scene-voice-empty">
            <p>光标未落在对话语句上。</p>
            <p className="scene-voice-hint">将光标移动到任意一句对话（旁白或人物台词）上，即可在此配置并生成配音。</p>
            {card.history.length > 0 && (
              <Button
                appearance="subtle"
                icon={<ArrowSyncRegular />}
                onClick={() => {
                  void voiceController.realignCard(docPath).then(() => setRefreshToken((token) => token + 1));
                }}
              >
                重新对齐 {card.history.length} 条配音记录
              </Button>
            )}
          </div>
        )}
      </div>

      <SceneConflictDialog
        open={conflictOpen}
        cardId={docPath}
        scenePath={docPath}
        inRepository={Boolean(projectPath && gitStatus)}
        onResolved={() => {
          setConflictOpen(false);
          setRefreshToken((token) => token + 1);
        }}
        onOpenGitMerge={() => {
          // 用 git 合并: 打开该文件与工作区的差异对比, 由用户在对比页里决定取舍
          if (projectPath) {
            useAppStore.getState().openTab(
              makeDiffTab({
                file: absToRel(projectPath, docPath),
                title: `${doc?.name ?? '场景'}（合并）`,
                diffKind: 'unstaged',
              })
            );
          }
          setConflictOpen(false);
        }}
      />
    </div>
  );
}

/** 与控制器一致的轻量内容哈希 */
function hash(text: string): string {
  let value = 0x811c9dc5;
  const normalized = text.replace(/\r\n/g, '\n');
  for (let index = 0; index < normalized.length; index++) {
    value ^= normalized.charCodeAt(index);
    value = Math.imul(value, 0x01000193);
  }
  return (value >>> 0).toString(16);
}
